1	/**
2	 * Error types raised by Server Actions that are *expected* failures rather
3	 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
4	 * the `AppErrorShape` the client form layer renders, mirroring the convention
5	 * already used by `PermissionDeniedError` and `TenantScopeError`.
6	 *
7	 * These live in `src/actions/_lib` because only the action layer produces
8	 * them — services throw their own domain errors, and repositories throw none.
9	 */
10	
11	import type { LimitedResource } from "@/types/billing";
12	import type { IsoTimestamp } from "@/types/common";
13	import type { PermissionAction } from "@/types/permission";
14	
15	/** No session at all, or a session whose active organization is gone. */
16	export class UnauthorizedActionError extends Error {
17	  readonly code = "unauthorized" as const;
18	
19	  constructor(message = "Sign in to continue.") {
20	    super(message);
21	    this.name = "UnauthorizedActionError";
22	  }
23	}
24	
25	/**
26	 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
27	 * `assertCan()` inside services) only in that the action layer already knows
28	 * the action name and does not need the full `PermissionDecision`.
29	 */
30	export class ForbiddenActionError extends Error {
31	  readonly code = "forbidden" as const;
32	
