function toEntries(specs: Spec[]): ManifestEntry[] {
  return specs.map(([path, responsibility, exports, mustUse]) => ({
    path,
    owner: "C" as const,
    responsibility,
    exports,
    mustUse: mustUse && mustUse.length > 0 ? mustUse : undefined,
  }));
}

